const n={loading:n=>{const{normalize:r}=n;return r(["ലോഡ് ചെയ്യുന്നു"])},Ranking:n=>{const{normalize:r}=n;return r(["റാങ്കിംഗ്"])},Daily:n=>{const{normalize:r}=n;return r(["ദിവസേന"])},Weekly:n=>{const{normalize:r}=n;return r(["ആഴ്ചതോറും"])},Monthly:n=>{const{normalize:r}=n;return r(["മാസംതോറും"])},Duration:n=>{const{normalize:r,interpolate:t,named:o}=n;return r(["സമയപരിധി ",t(o("duration"))])},OnlyShowTop:n=>{const{normalize:r,interpolate:t,named:o}=n;return r(["റാങ്കിംഗ് ലിസ്റ്റിൽ ഏറ്റവും മികച്ച ",t(o("num"))," എണ്ണം മാത്രമേ കാണിക്കൂ"])},i_got_it:n=>{const{normalize:r}=n;return r(["നേടുക"])},levelCount:n=>{const{normalize:r,interpolate:t,named:o}=n;return r(["Lv.",t(o("count"))])},honor:n=>{const{normalize:r}=n;return r(["ഓണർ"])},charm:n=>{const{normalize:r}=n;return r(["ചാം"])},room:n=>{const{normalize:r}=n;return r(["റൂം"])},honor_tip:n=>{const{normalize:r}=n;return r(["നിങ്ങൾ അയയ്ക്കുന്ന കോയിനുകളുടെ എണ്ണത്തെ അടിസ്ഥാനമാക്കിയാണ് ഓണർ റാങ്കിംഗ് നിർണ്ണയിക്കുന്നത്, കോയിനുകളുടെ മൂല്യത്തിന്റെ 20% മാത്രമേ ലക്കി ഗിഫ്റ്റിന് കണക്കാക്കൂ."])},charm_tip:n=>{const{normalize:r}=n;return r(["നിങ്ങൾ സ്വീകരിക്കുന്ന ഡയമണ്ടുകളുടെ എണ്ണത്തെ അടിസ്ഥാനമാക്കിയാണ് ചാം റാങ്കിംഗ് നിർണ്ണയിക്കുന്നത്, ഡയമണ്ട് മൂല്യത്തിന്റെ 20% മാത്രമേ ലക്കി ഗിഫ്റ്റിന് കണക്കാക്കൂ."])},room_tip:n=>{const{normalize:r}=n;return r(["റൂമിൽ സ്വീകരിക്കുന്ന കോയിനുകളുടെ എണ്ണത്തെ അടിസ്ഥാനമാക്കിയാണ് റൂം റാങ്കിംഗ് നിർണ്ണയിക്കുന്നത്, കോയിനുകളുടെ മൂല്യത്തിന്റെ 20% മാത്രമേ ലക്കി ഗിഫ്റ്റിന് കണക്കാക്കൂ."])},viewLimit:n=>{const{normalize:r}=n;return r(["Lv.10 അല്ലെങ്കിൽ അതിന് മുകളിലുള്ളവർക്ക് മാത്രമേ കാണാൻ കഴിയൂ."])},statementLang:n=>{const{normalize:r}=n;return r(["ഈ ഇവന്റ് Google Play-മായി ബന്ധപ്പെട്ടതല്ല. എല്ലാ അവകാശങ്ങളും ഈ ആപ്പിന് നിക്ഷിപ്തമാണ്."])},statementIosLang:n=>{const{normalize:r}=n;return r(["ഈ ഇവന്റ് Apple Inc.-മായി ബന്ധപ്പെട്ടതല്ല. എല്ലാ അവകാശങ്ങളും ഈ ആപ്പിന് നിക്ഷിപ്തമാണ്."])}};export{n as default};
